    if n.get("max_turn_transition"):
        assert n["max_turn_transition"] in nodes

if __name__ == "__main__":
    json.dump(wf, open(OUT, "w", encoding="utf-8"), indent=1, ensure_ascii=False)
    print("wrote", OUT, len(nodes), "nodes")

