            return v if re.fullmatch(r'\d{5}', v) else None
        return v if re.fullmatch(r'\d+', v) else None
    if fmt == 'amount':
        v2 = re.sub(r'[^\d.,]', '', v).replace(',', '')
        if not re.fullmatch(r'\d+(\.\d{1,2})?', v2):
