CLOSE_POST = COMMON + r'''
try:
    d = _d(result)
    if d is not None and str(d.get('ok')).lower() == 'true':
        vars['close_state'] = 'closed'
        d['what_to_do_next'] = 'The call is closed. Say nothing more.'
