                d['what_to_do_next'] = 'All answers are saved.'
        else:
            vars['fields_state'] = 'complete'
            vars['submit_answer'] = 'none'
            d['what_to_do_next'] = 'All answers are saved.'
except StopIteration:
    pass
except Exception:
    pass
'''

